(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.33)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const w2x = Math.sin(w1x*0.03+t*0.5)*6 + Math.cos(w1y*0.025-t*0.4)*5;
  const w2y = Math.cos(w1y*0.028-t*0.45)*6 + Math.sin(w1x*0.022+t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 4.3],
    [400+Math.cos(t*0.55+1)*60, 210+Math.sin(t*0.75+4)*45, 0.085, 1.8, 2.9]
  ];
  let aS=0, iS=0, cross=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp+ph);
    const i=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    aS+=a; iS+=i; cross+=a*i*0.3;
  }
  const act=aS/8, inh=iS/8, cr=cross/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.06*Math.sin(t*0.13)+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*5+t*0.9)*0.2;
  const pulse=Math.sin(t*1.2)*0.15*Math.exp(-dist*0.008);
  const feedback=Math.tanh(act*1.5)*Math.sin(inh*Math.PI)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cr*0.5+feedback+pulse)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.08*Math.abs(reaction);
  const blend=reaction*0.6+cell*0.25+micro, v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[10,30,80],[12,65,105],[18,110,120],
    [45,155,130],[140,185,95],[210,190,60],[220,140,55],
    [200,85,65],[160,45,75],[100,25,65],[45,15,55],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.08:1.0;
  const glow=Math.max(0,reaction-0.3)*0.4;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)
  ];
}
